import {occupancy} from './utilities.js?v=civic-advisors-2';
// Manual pp.103,112 specifies causal relationships; coefficients are recreation tuning.
export function healthOutlook(c){
 let population=0,air=0,water=0,care=0,recreation=0,garbage=0,garbageRisk=0;
 for(const t of c.tiles){if(t.type!=='residential'||!t.level)continue;const people=occupancy(t.level)*8;population+=people;air+=(t.airPollution||0)*people;water+=(t.waterPollution||0)*people;care+=(t.healthCoverage||0)*people;recreation+=(t.recreationHealth||0)*people;garbage+=(t.waste||0)*people;garbageRisk+=Math.min(1,Math.max(0,t.waste||0)/50)*people;}
 const avg=n=>population?n/population:0;
 const airExposure=avg(air),waterExposure=avg(water),hospitalBenefit=avg(care)*.31,recreationBenefit=avg(recreation),airPenalty=airExposure*.1,waterPenalty=waterExposure*.1;
 // Fifty units of uncollected waste at a home reaches the maximum direct
 // sanitation penalty. These thresholds are explicit reconstruction tuning.
 const garbageExposure=avg(garbage),garbagePenalty=avg(garbageRisk)*15;
 const clinicBenefit=c.civic.ordinances.freeClinics?3:0;
 return{garbageExposure,garbagePenalty,clinicBenefit,population,airExposure,waterExposure,hospitalBenefit,recreationBenefit,airPenalty,waterPenalty,target:Math.max(45,Math.min(90,59+hospitalBenefit+recreationBenefit+clinicBenefit-airPenalty-waterPenalty-garbagePenalty))};
}
export function healthReport(c){const h=healthOutlook(c),f=n=>n.toFixed(1);return `<details><summary>What affects life expectancy?</summary>${h.population?`<p>At current conditions, life expectancy is moving toward ${f(h.target)} years. Changes take several years to develop. Longer life expectancy increases workforce participation; the Population report shows the effect.</p><div class="table-scroll"><table><thead><tr><th>Factor</th><th>Effect on long-term target</th></tr></thead><tbody><tr><td>Baseline</td><td>59 years</td></tr><tr><td>Accessible hospital care</td><td>+${f(h.hospitalBenefit)} years</td></tr><tr><td>Free clinics</td><td>+${f(h.clinicBenefit)} years</td></tr><tr><td>Recreation</td><td>+${f(h.recreationBenefit)} years</td></tr><tr><td>Air pollution near homes</td><td>−${f(h.airPenalty)} years</td></tr><tr><td>Uncollected garbage at homes</td><td>−${f(h.garbagePenalty)} years</td></tr><tr><td>Water pollution near homes</td><td>−${f(h.waterPenalty)} years</td></tr></tbody></table></div><p>Residential exposure: air ${f(h.airExposure)}/100; water ${f(h.waterExposure)}/100; uncollected garbage ${f(h.garbageExposure)} units per occupied tile. More residents give a neighborhood more weight. The target stays between 45 and 90 years.</p><p>Keep hospitals connected and funded, separate homes from polluting industry, reduce traffic emissions, and connect homes to adequate garbage collection. Pollution and garbage can offset the benefits of hospital care.</p>`:'<p>No residents yet. Health begins changing when residents move in.</p>'}</details>`;}
